const $=s=>document.querySelector(s),client=window.lookalikeSupabaseClient;
const BASE='https://dphiuepbsullrscuuzrc.supabase.co',KEY='sb_publishable_kmj9VR5ie5sFFQvGm9TcSw_MbBGUMtq',QUEUE='https://im-king-analysis-queue.im-king-analysis-queue.workers.dev';
const labels={'profile.created':'프로필 생성','profile.nickname_changed':'닉네임 변경','post.submitted':'게시물 제출','post.deleted':'게시물 삭제','post.approved':'게시물 승인','post.rejected':'게시물 반려','post.changes':'게시물 수정 요청','post.hidden':'게시물 숨김','post.edited':'게시물 수정','post.photo_changed':'게시물 사진 연결 변경','post.liked':'좋아요 추가','post.unliked':'좋아요 취소','post.like_cleanup':'게시물 삭제에 따른 좋아요 정리','dataset.hidden':'데이터셋 공개 제외','dataset.restored':'데이터셋 공개 복원','user.role_changed':'사용자 권한 변경','dataset.updated':'데이터셋 정보 수정','photo.deleted':'기준 사진 삭제','photo.restored':'기준 사진 복원','photo.registered':'기준 사진 등록','import.requested':'사진 등록 접수','import.complete':'사진 등록 완료','import.failed':'사진 등록 실패','import.expired':'사진 등록 시간 초과','analysis.requested':'닮은꼴 분석 접수','analysis.complete':'닮은꼴 분석 완료','analysis.failed':'닮은꼴 분석 실패','analysis.expired':'닮은꼴 분석 시간 초과'};
labels['photo.attributes_updated']='사진 특징 수정';
labels['dataset.gender_updated']='성별 분류 수정';
Object.assign(labels,{'frame.created':'프레임 등록','frame.updated':'프레임 수정','frame.published':'프레임 공개','frame.unpublished':'프레임 비공개 전환'});
let before=null,count=0,requestVersion=0,controller,allowed=false;
function actions(){const select=$('#logAction');select.replaceChildren(new Option('전체 작업',''));const list=$('#logSource').value==='service'?[['post.','게시물·좋아요'],['profile.','프로필·닉네임'],['user.','권한 변경'],['dataset.','데이터셋 공개 설정'],['frame.','프레임 관리']]:[['analysis.','닮은꼴 분석'],['import.','사진 등록 처리'],['photo.','기준 사진'],['dataset.','데이터셋 정보']];for(const [value,name] of list)select.add(new Option(name,value));}
function renderEntry(row){const card=document.createElement('article');card.className='log-entry';const header=document.createElement('header'),heading=document.createElement('h2'),time=document.createElement('time'),state=document.createElement('span');heading.textContent=labels[row.action]||row.action;state.className='log-outcome';state.dataset.state=row.outcome;state.textContent=({success:'완료',accepted:'접수',failed:'실패·만료'})[row.outcome]||row.outcome;heading.append(state);time.dateTime=new Date(row.created_at).toISOString();time.textContent=new Intl.DateTimeFormat('ko-KR',{dateStyle:'medium',timeStyle:'medium',timeZone:'Asia/Seoul'}).format(new Date(row.created_at));header.append(heading,time);const actor=document.createElement('p'),target=document.createElement('p');actor.textContent='작업자 · '+(row.actor_name||row.actor_id||'비로그인 사용자 / 시스템');target.textContent='대상 · '+row.target_id;const details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent='세부 기록 보기';pre.textContent=JSON.stringify({기록_ID:row.id,작업:row.action,작업자_ID:row.actor_id||null,...row.details},null,2);details.append(summary,pre);card.append(header,actor,target,details);return card;}
async function load(reset=true){if(!allowed)return;const version=++requestVersion;controller?.abort();controller=new AbortController();const timer=setTimeout(()=>controller?.abort(),15000);if(reset){before=null;count=0;$('#logList').replaceChildren();}$('#logMore').hidden=true;$('#logStatus').textContent='기록을 불러오는 중…';
 try{const {data:{session}}=await client.auth.getSession();if(!session)throw Error('로그인이 만료되었습니다. 다시 로그인해 주세요.');const action=$('#logAction').value,q=$('#logQuery').value.trim(),headers={Authorization:'Bearer '+session.access_token};let response;
 if($('#logSource').value==='service')response=await fetch(BASE+'/rest/v1/rpc/owner_activity_logs',{method:'POST',headers:{...headers,apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({before_id:before,action_prefix:action,search_text:q}),signal:controller.signal});
 else{const params=new URLSearchParams({action,q});if(before)params.set('before',before);response=await fetch(QUEUE+'/dataset/admin-logs?'+params,{headers,cache:'no-store',signal:controller.signal});}
 if(version!==requestVersion)return;if(!response.ok){if([401,403].includes(response.status)){$('#logList').replaceChildren();count=0;throw Error('최고 관리자 권한이 필요합니다. 로그인 상태를 확인해 주세요.');}throw Error('기록을 불러오지 못했습니다. 새로고침해 주세요.');}
 const data=await response.json();if(version!==requestVersion)return;const rows=Array.isArray(data)?data:data.items;const more=rows.length>50;const page=rows.slice(0,50);for(const row of page)$('#logList').append(renderEntry(row));if(page.length)before=page.at(-1).id;count+=page.length;$('#logMore').hidden=!more;$('#logStatus').textContent=count?count+'건 표시 · 최신순':'조건에 맞는 기록이 없습니다. 적용 이전 작업은 소급 기록되지 않습니다.';
 }catch(error){if(version!==requestVersion)return;$('#logStatus').textContent=error.name==='AbortError'?'응답이 지연되고 있습니다. 새로고침해 주세요.':error.message;}finally{clearTimeout(timer);}}
$('#logFilters').onsubmit=e=>{e.preventDefault();load();};$('#logRefresh').onclick=()=>load();$('#logMore').onclick=()=>load(false);$('#logSource').onchange=()=>{actions();load();};$('#logAction').onchange=()=>load();
try{const {data:{session}}=await client.auth.getSession();if(!session)throw Error('최고 관리자 계정으로 로그인해 주세요.');const response=await fetch(BASE+'/rest/v1/rpc/my_admin_role',{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:'{}',signal:AbortSignal.timeout(10000)});if(!response.ok||await response.json()!=='owner')throw Error('최고 관리자만 작업 로그를 확인할 수 있습니다.');allowed=true;$('#logAccess').hidden=true;$('#logConsole').hidden=false;actions();await load();}catch(error){$('#logAccess').textContent=error.message;}
client.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){allowed=false;controller?.abort();requestVersion++;$('#logConsole').hidden=true;$('#logList').replaceChildren();$('#logAccess').hidden=false;$('#logAccess').textContent='최고 관리자 계정으로 다시 로그인해 주세요.';}});
